<?php require_once __DIR__.'/../../config/seguranca.php';exigirAdmin();$pageTitle='Estoque';require __DIR__.'/../_header.php';$pdo=getPDO();$rows=$pdo&&tableExists($pdo,'produtos')?$pdo->query('SELECT p.id,p.nome,c.nome categoria,p.estoque,p.preco,p.ativo FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id ORDER BY p.estoque ASC,p.nome')->fetchAll():[];?><div class="admin-heading"><div><h1>Estoque</h1><p>Visualize os produtos e identifique itens com baixa disponibilidade.</p></div><a class="admin-btn" href="<?=url('admin/produtos/index.php')?>">Gerenciar produtos</a></div><div class="admin-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Produto</th><th>Categoria</th><th>Quantidade</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):$qty=(int)$r['estoque'];?><tr><td><?=e($r['nome'])?></td><td><?=e($r['categoria']??'')?></td><td><?=e($qty)?></td><td class="<?=$qty<=2?'stock-low':'stock-ok'?>"><strong><?=$qty<=2?'Baixo':'Normal'?></strong></td><td><a class="mini-btn" href="<?=url('admin/produtos/editar.php?id='.$r['id'])?>">Ajustar</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../_footer.php'; ?>
